UPDATE TEAM_MEMBER
SET ROLE = #{role}
WHERE TEAM_MEMBER_NUM = #{team_member_num}

UPDATE TEAM_MEMBER
SET JOIN_STATUS = 2,
    EXITED_AT   = SYSDATE
WHERE TEAM_NUM = #{teamNum}
  AND USER_NUM  = #{userNum}

UPDATE TEAM_MEMBER
SET JOIN_STATUS = 3,
    EXITED_AT   = SYSDATE
WHERE TEAM_NUM = #{teamNum}
  AND USER_NUM  = #{userNum}
